From 50b1c871c853ab79b120c89ded215f8140779a57 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:50:07 +0100
Subject: [PATCH] applets/weather: show sunrise and sunset times

The widget only used sunrise and sunset internally to pick day or night
icons, so there was no way to see them. Compute them from the station's
coordinates for every provider and list them in the details view.

BUG: 521202
---
 applets/weather/CMakeLists.txt      |  1 +
 applets/weather/qml/DetailsView.qml | 15 +++++++++++++++
 applets/weather/qml/TopPanel.qml    |  1 +
 applets/weather/util.cpp            | 11 +++++++++++
 applets/weather/util.h              |  3 +++
 5 files changed, 31 insertions(+)

diff --git a/applets/weather/CMakeLists.txt b/applets/weather/CMakeLists.txt
index d0b4b3c01..e9433089a 100644
--- a/applets/weather/CMakeLists.txt
+++ b/applets/weather/CMakeLists.txt
@@ -91,6 +91,7 @@ ecm_qt_declare_logging_category(org.kde.plasma.weather
 target_link_libraries(org.kde.plasma.weather PRIVATE
     KF6::UnitConversion
     KF6::I18n
+    KF6::Holidays
     Qt::Core
     Qt::DBus
     Qt::Qml
diff --git a/applets/weather/qml/DetailsView.qml b/applets/weather/qml/DetailsView.qml
index 02a45f196..ae6a55a8d 100644
--- a/applets/weather/qml/DetailsView.qml
+++ b/applets/weather/qml/DetailsView.qml
@@ -15,6 +15,7 @@ RowLayout {

     property var lastObservation: null
     property var metaData: null
+    property var station: null

     property int invalidUnit: 0
     property int displayTemperatureUnit: 0
@@ -30,6 +31,10 @@ RowLayout {
         property bool available: true
     }

+    readonly property bool hasCoordinates: !isNaN(root.station?.latitude) && !isNaN(root.station?.longitude)
+    readonly property date sunrise: hasCoordinates ? Util.sunrise(root.station.latitude, root.station.longitude) : new Date(NaN)
+    readonly property date sunset: hasCoordinates ? Util.sunset(root.station.latitude, root.station.longitude) : new Date(NaN)
+
     readonly property list<DetailsString> detailsModel: [
         DetailsString {
             label: i18nc("@label ground temperature", "Dewpoint")
@@ -73,6 +78,16 @@ RowLayout {
             label: i18nc("@label", "Wind speed")
             text: available ? Util.valueToDisplayString(root.displaySpeedUnit, root.lastObservation.windSpeed, root.metaData.windSpeedUnit, 1) : ""
             available: !isNaN(root.lastObservation?.windSpeed) && root.lastObservation.windSpeed !== 0.0 && !!root.metaData?.windSpeedUnit
+        },
+        DetailsString {
+            label: i18nc("@label", "Sunrise")
+            text: available ? Qt.formatTime(root.sunrise, Qt.locale().timeFormat(Locale.ShortFormat)) : ""
+            available: !isNaN(root.sunrise)
+        },
+        DetailsString {
+            label: i18nc("@label", "Sunset")
+            text: available ? Qt.formatTime(root.sunset, Qt.locale().timeFormat(Locale.ShortFormat)) : ""
+            available: !isNaN(root.sunset)
         }
     ]

diff --git a/applets/weather/qml/TopPanel.qml b/applets/weather/qml/TopPanel.qml
index 1b6ebee17..085401414 100644
--- a/applets/weather/qml/TopPanel.qml
+++ b/applets/weather/qml/TopPanel.qml
@@ -162,6 +162,7 @@ ColumnLayout {

             metaData: root.metaData
             lastObservation: root.lastObservation
+            station: root.station
         }
     }
 }
diff --git a/applets/weather/util.cpp b/applets/weather/util.cpp
index 2c8e7a0dd..44ebecaa1 100644
--- a/applets/weather/util.cpp
+++ b/applets/weather/util.cpp
@@ -7,6 +7,7 @@
 #include "util.h"

 // KF
+#include <KHolidays/SunEvents>
 #include <KLocalizedString>
 #include <KUnitConversion/Value>
 // Qt
@@ -73,4 +74,14 @@ QString Util::nameFromUnitId(KUnitConversion::UnitId unitId)
     return unitDescription;
 }

+QDateTime Util::sunrise(double latitude, double longitude) const
+{
+    return KHolidays::SunEvents(QDateTime::currentDateTime(), latitude, longitude).sunrise();
+}
+
+QDateTime Util::sunset(double latitude, double longitude) const
+{
+    return KHolidays::SunEvents(QDateTime::currentDateTime(), latitude, longitude).sunset();
+}
+
 #include "moc_util.cpp"
diff --git a/applets/weather/util.h b/applets/weather/util.h
index 3407a4b44..a01ddb8d9 100644
--- a/applets/weather/util.h
+++ b/applets/weather/util.h
@@ -9,6 +9,7 @@
 // KF
 #include <KUnitConversion/Converter>
 // Qt
+#include <QDateTime>
 #include <QObject>

 #include <qqmlintegration.h>
@@ -28,6 +29,8 @@ public:
     Q_INVOKABLE QString temperatureToDisplayString(int displayUnitType, double value, int valueUnitType, bool rounded = false, bool degreesOnly = false) const;
     Q_INVOKABLE QString valueToDisplayString(int displayUnitType, double value, int valueUnitType, int precision = 0) const;
     Q_INVOKABLE QString percentToDisplayString(double value) const;
+    Q_INVOKABLE QDateTime sunrise(double latitude, double longitude) const;
+    Q_INVOKABLE QDateTime sunset(double latitude, double longitude) const;

     static QString nameFromUnitId(KUnitConversion::UnitId unitId);

-- 
